begin;
set local search_path=public,extensions;
select plan(48);

select ok((select count(*)=12 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname=any(array[
  'third_party_services','third_party_service_alerts','continuity_service_objectives','restore_test_evidence',
  'security_control_evidence','security_incidents','organization_exit_requests','organization_export_artifacts',
  'session_revocation_batches','operational_jobs','operational_job_attempts','dead_letter_reprocess_requests'
])), 'V4.1 resilience/security tables exist');
select ok((select count(*)=12 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array[
  'third_party_services','third_party_service_alerts','continuity_service_objectives','restore_test_evidence',
  'security_control_evidence','security_incidents','organization_exit_requests','organization_export_artifacts',
  'session_revocation_batches','operational_jobs','operational_job_attempts','dead_letter_reprocess_requests'
])), 'RLS is enabled on all new exposed tables');
select ok((select count(*)=12 from pg_policies where schemaname='public' and tablename=any(array[
  'third_party_services','third_party_service_alerts','continuity_service_objectives','restore_test_evidence',
  'security_control_evidence','security_incidents','organization_exit_requests','organization_export_artifacts',
  'session_revocation_batches','operational_jobs','operational_job_attempts','dead_letter_reprocess_requests'
])), 'every new table has an explicit restrictive read policy');
select ok(not has_table_privilege('authenticated','public.third_party_services','INSERT') and not has_table_privilege('authenticated','public.operational_jobs','UPDATE'), 'authenticated users cannot bypass command functions');
select ok(not has_table_privilege('service_role','public.security_control_evidence','INSERT') and not has_table_privilege('service_role','public.dead_letter_reprocess_requests','UPDATE'), 'service role has no broad direct table bypass');

select ok(exists(select 1 from pg_constraint where conrelid='public.third_party_services'::regclass and contype='c' and pg_get_constraintdef(oid) like '%secret_names%'), 'technology registry stores secret names only under a structural guard');
select ok(exists(select 1 from pg_constraint where conrelid='public.third_party_services'::regclass and contype='c' and pg_get_constraintdef(oid) like '%REQUIRED_NOT_COMPLETED%'), 'external DPA/security gaps are represented honestly');
select ok(exists(select 1 from pg_constraint where conrelid='public.continuity_service_objectives'::regclass and contype='c' and pg_get_constraintdef(oid) like '%rpo_minutes%rto_minutes%'), 'RPO and RTO are positive and explicit');
select ok(exists(select 1 from pg_constraint where conrelid='public.restore_test_evidence'::regclass and contype='c' and pg_get_constraintdef(oid) like '%executed_at%' and pg_get_constraintdef(oid) like '%evidence_hash%'), 'restore evidence cannot claim execution without timestamp and hash');
select ok(exists(select 1 from pg_constraint where conrelid='public.security_control_evidence'::regclass and contype='c' and pg_get_constraintdef(oid) like '%REQUIRED_NOT_COMPLETED%'), 'unexecuted security controls remain explicit');
select ok(exists(select 1 from pg_constraint where conrelid='public.organization_export_artifacts'::regclass and contype='c' and pg_get_constraintdef(oid) like '%sha256%'), 'exports carry an integrity hash');
select ok(exists(select 1 from pg_constraint where conrelid='public.operational_jobs'::regclass and contype='c' and pg_get_constraintdef(oid) like '%attempt_count%max_attempts%'), 'job retries are bounded');
select ok(exists(select 1 from pg_constraint where conrelid='public.operational_jobs'::regclass and contype='c' and pg_get_constraintdef(oid) like '%redacted_payload%'), 'job payloads reject secret-bearing top-level keys');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='operational_jobs_dispatch_idx'), 'ready jobs have a bounded dispatch index');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='third_party_service_alerts_open_idx'), 'open dependency alerts are indexed');

select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array[
  'register_third_party_service_version','record_restore_test_result','request_organization_export','request_dead_letter_reprocess','decide_dead_letter_reprocess'
])), 'five V4.1 commands are SECURITY DEFINER with fixed search paths');
select ok((select pg_get_functiondef(p.oid) like '%auth.jwt()%aal%aal2%' and pg_get_functiondef(p.oid) like '%SUPER_ADMIN%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='register_third_party_service_version'), 'technology registry mutation requires central AAL2');
select ok((select pg_get_functiondef(p.oid) like '%REQUIRED_NOT_COMPLETED%' and pg_get_functiondef(p.oid) like '%evidence_hash%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_restore_test_result'), 'restore command distinguishes proof from outstanding work');
select ok((select pg_get_functiondef(p.oid) like '%has_org_role%' and pg_get_functiondef(p.oid) like '%aal2%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='request_organization_export'), 'sensitive organization export requires tenant authority and step-up');
select ok((select pg_get_functiondef(p.oid) like '%begin_admin_command%' and pg_get_functiondef(p.oid) like '%event_outbox%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='request_dead_letter_reprocess'), 'DLQ reprocess request is idempotent and emits Outbox');
select ok((select pg_get_functiondef(p.oid) like '%requested_by=a%' and pg_get_functiondef(p.oid) like '%DUAL_CONTROL_REQUIRED%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='decide_dead_letter_reprocess'), 'DLQ reprocessing enforces four-eyes');
select ok((select pg_get_functiondef(p.oid) like '%unique_violation%' and pg_get_functiondef(p.oid) like '%REPROCESS_ALREADY_ENQUEUED%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='decide_dead_letter_reprocess'), 'reprocessing is idempotent at enqueue time');
select ok((select pg_get_functiondef(p.oid) like '%audit_events%' and pg_get_functiondef(p.oid) like '%event_outbox%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='request_organization_export'), 'export requests are audited and emitted');

select ok((select count(*)=7 from pg_trigger where tgname=any(array[
  'third_party_service_history_immutable','third_party_alert_history_immutable','continuity_objective_history_immutable',
  'restore_evidence_immutable','security_control_evidence_immutable','export_artifact_immutable','job_attempt_history_immutable'
]) and not tgisinternal), 'configuration and evidence history is append-only');
select ok((select count(*)=9 from public.third_party_services where status='ACTIVE'), 'critical technology dependency baseline is seeded without credentials');
select ok((select bool_and(secret_names <@ array['SUPABASE_SERVICE_ROLE_KEY','VERCEL_TOKEN','RAILWAY_TOKEN','OPENAI_API_KEY','RESEND_API_KEY']::text[]) from public.third_party_services), 'seed contains only approved environment variable names');
select ok((select count(*)=9 and bool_and(dpa_status='REQUIRED_NOT_COMPLETED') from public.third_party_services), 'external DPA verification is not falsely declared complete');
select ok((select count(*)=9 and bool_and(status='REQUIRED_NOT_COMPLETED') from public.restore_test_evidence), 'restore tests are outstanding until external execution evidence exists');
select ok((select count(*)>=6 from public.security_control_evidence where status='REQUIRED_NOT_COMPLETED'), 'security scans and controls are registered as externally outstanding');
select ok((select count(*)=9 and bool_and(alternative_provider is not null and length(exit_plan)>=20) from public.third_party_services), 'critical providers have alternatives and exit plans');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('a1130000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','admin1-113@example.invalid','',now(),'{}','{}',now(),now()),
('a1130000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','admin2-113@example.invalid','',now(),'{}','{}',now(),now()),
('a1130000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','tenant-a-113@example.invalid','',now(),'{}','{}',now(),now()),
('a1130000-0000-4000-8000-000000000004','00000000-0000-0000-0000-000000000000','authenticated','authenticated','tenant-b-113@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values
('b1130000-0000-4000-8000-000000000001','Tenant A 113','Tenant A 113','ACTIVE','a1130000-0000-4000-8000-000000000003'),
('b1130000-0000-4000-8000-000000000002','Tenant B 113','Tenant B 113','ACTIVE','a1130000-0000-4000-8000-000000000004');
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values
('c1130000-0000-4000-8000-000000000001','b1130000-0000-4000-8000-000000000001','a1130000-0000-4000-8000-000000000003','ACTIVE',now()),
('c1130000-0000-4000-8000-000000000002','b1130000-0000-4000-8000-000000000002','a1130000-0000-4000-8000-000000000004','ACTIVE',now());
insert into public.organization_member_roles(membership_id,role_code)values
('c1130000-0000-4000-8000-000000000001','CLIENT_ADMIN'),('c1130000-0000-4000-8000-000000000002','CLIENT_ADMIN');
insert into public.platform_user_roles(user_id,role_code)values
('a1130000-0000-4000-8000-000000000001','SUPER_ADMIN'),('a1130000-0000-4000-8000-000000000002','MATRICIA_ADMIN');

select throws_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.enqueue_operational_job('b1130000-0000-4000-8000-000000000001','EMAIL_SEND','RESEND','d1130000-0000-4000-8000-000000000001','evt-113','{"safe":{"nested":{"token":"masked"}}}',3,'e1130000-0000-4000-8000-000000000001');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'22023','SENSITIVE_JOB_PAYLOAD_REJECTED','DENY nested sensitive job field');
select lives_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.enqueue_operational_job('b1130000-0000-4000-8000-000000000001','EMAIL_SEND','RESEND','d1130000-0000-4000-8000-000000000001','evt-113','{"aggregate_id":"safe"}',3,'e1130000-0000-4000-8000-000000000002');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'ALLOW service role enqueues a redacted job');
select lives_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.enqueue_operational_job('b1130000-0000-4000-8000-000000000001','EMAIL_SEND','RESEND','d1130000-0000-4000-8000-000000000001','evt-113','{"aggregate_id":"safe"}',3,'e1130000-0000-4000-8000-000000000003');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'ALLOW exact enqueue replay returns cached job');
select ok((select count(*)=1 from public.operational_jobs where request_id='d1130000-0000-4000-8000-000000000001'),'enqueue replay creates one job');
select throws_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.enqueue_operational_job('b1130000-0000-4000-8000-000000000002','EMAIL_SEND','RESEND','d1130000-0000-4000-8000-000000000001','evt-113','{"aggregate_id":"altered"}',3,'e1130000-0000-4000-8000-000000000004');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'22000','JOB_IDEMPOTENCY_PAYLOAD_MISMATCH','DENY altered enqueue replay including tenant change');

select lives_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.record_operational_job_attempt((select id from public.operational_jobs where request_id='d1130000-0000-4000-8000-000000000001'),'RETRYABLE_FAILURE','PROVIDER_TIMEOUT',120,repeat('a',64),'2026-09-13T00:00:00Z','2026-09-13T00:00:01Z','attempt-113-0001','e1130000-0000-4000-8000-000000000005');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'ALLOW first provider attempt');
select lives_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.record_operational_job_attempt((select id from public.operational_jobs where request_id='d1130000-0000-4000-8000-000000000001'),'RETRYABLE_FAILURE','PROVIDER_TIMEOUT',120,repeat('a',64),'2026-09-13T00:00:00Z','2026-09-13T00:00:01Z','attempt-113-0001','e1130000-0000-4000-8000-000000000006');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'ALLOW exact attempt replay without consuming retry');
select is((select attempt_count from public.operational_jobs where request_id='d1130000-0000-4000-8000-000000000001'),1,'attempt replay consumes one retry only');
select throws_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.record_operational_job_attempt((select id from public.operational_jobs where request_id='d1130000-0000-4000-8000-000000000001'),'TERMINAL_FAILURE','ALTERED',120,repeat('a',64),'2026-09-13T00:00:00Z','2026-09-13T00:00:01Z','attempt-113-0001','e1130000-0000-4000-8000-000000000007');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'22000','JOB_ATTEMPT_REPLAY_MISMATCH','DENY altered provider attempt replay');

select lives_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a1130000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a1130000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);select public.request_organization_export('b1130000-0000-4000-8000-000000000001',jsonb_build_object('subject_reference_hash',repeat('1',64)),'RETENTION-V1','Authorized organization exit request','export-113-0001','e1130000-0000-4000-8000-000000000008');reset role$$,'ALLOW tenant owner requests own export');
create temporary table p113_cross_tenant_observed(row_count bigint);grant insert,select on p113_cross_tenant_observed to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','a1130000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a1130000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
insert into p113_cross_tenant_observed select count(*) from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001';
reset role;select ok((select row_count=0 from p113_cross_tenant_observed),'DENY cross-tenant exit request read');

select lives_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a1130000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a1130000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);select public.advance_organization_exit((select id from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001'),'IDENTITY_VERIFIED','Independent identity verification','exit-113-step-01','e1130000-0000-4000-8000-000000000009');select public.advance_organization_exit((select id from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001'),'IDENTITY_VERIFIED','Independent identity verification','exit-113-step-01','e1130000-0000-4000-8000-000000000010');select public.advance_organization_exit((select id from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001'),'LEGAL_REVIEW','Legal retention review completed','exit-113-step-02','e1130000-0000-4000-8000-000000000011');reset role$$,'ALLOW exit transition replay after state change returns idempotent response');

select lives_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.record_organization_export_artifact((select id from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001'),'ORGANIZATION_DATA','exports/tenant-a-113.json',repeat('b',64),1024,clock_timestamp()+interval'30 days','e1130000-0000-4000-8000-000000000012');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'ALLOW first export artifact evidence');
select lives_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.record_organization_export_artifact((select id from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001'),'ORGANIZATION_DATA','exports/tenant-a-113.json',repeat('b',64),1024,(select retention_until from public.organization_export_artifacts where organization_id='b1130000-0000-4000-8000-000000000001'),'e1130000-0000-4000-8000-000000000013');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'ALLOW exact export artifact replay');
select throws_ok($$select set_config('request.jwt.claim.role','service_role',true);select set_config('request.jwt.claims','{"role":"service_role"}',true);select public.record_organization_export_artifact((select id from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001'),'ORGANIZATION_DATA','exports/tenant-a-113-altered.json',repeat('c',64),1024,(select retention_until from public.organization_export_artifacts where organization_id='b1130000-0000-4000-8000-000000000001'),'e1130000-0000-4000-8000-000000000014');select set_config('request.jwt.claim.role','',true);select set_config('request.jwt.claims','{}',true)$$,'22000','EXPORT_ARTIFACT_REPLAY_MISMATCH','DENY altered export evidence replay');

update public.organization_exit_requests set status='ARCHIVED',approved_by='a1130000-0000-4000-8000-000000000002',approved_at=now() where organization_id='b1130000-0000-4000-8000-000000000001';
insert into public.privacy_legal_holds(organization_id,subject_reference_hash,reason_code,status,starts_at,evidence_reference,created_by)values('b1130000-0000-4000-8000-000000000001',repeat('1',64),'DISPUTE','ACTIVE',now(),'evidence/hold-113','a1130000-0000-4000-8000-000000000001');
select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a1130000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a1130000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);select public.advance_organization_exit((select id from public.organization_exit_requests where organization_id='b1130000-0000-4000-8000-000000000001'),'PURGED','Purge after archive request','exit-113-purge-01','e1130000-0000-4000-8000-000000000015');reset role$$,'55000','LEGAL_HOLD_BLOCKS_PURGE','DENY purge while privacy legal hold is active');
select ok((select strpos(prosrc,'begin_admin_command')<strpos(prosrc,'status<>') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_dead_letter_reprocess'),'DLQ decision checks idempotent replay before mutable state');
select ok((select strpos(prosrc,'begin_contract_command')<strpos(prosrc,'requested_by=a') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_organization_exit'),'exit transition checks idempotent replay before mutable state');

select * from finish();
rollback;
